//! The carillon discharge-plan family exercised end to end through
//! provider dispatch: `qtsl_cell_cover` and `qtsl_lowbound_boxes` at
//! full recompute (reference-anchored goldens, named data mutants —
//! every mutant flips a verdict — and refusal classes);
//! `qtsl_dbar_closure` and `qtsl_gap_a` as the event-3 loud-refusal
//! fibers (the manifest jump/switch slice left the theory — the
//! module doc's story), pinned here by message. The frozen
//! cross-implementation corpus replay
//! (`fixtures/carillon_pyref_corpus.json`, generated by the
//! independent python reference `fixtures/carillon_pyref_gen.py`:
//! Fraction arithmetic throughout, and a genuinely different coverage
//! decision — measure accounting over the cut grid where the
//! evaluator checks per-sub-cell containment) still replays ALL FOUR
//! kinds: cell_cover/floor_boxes through provider dispatch, dbar/
//! gap_a against the retained PURE core (`check_dbar_closure`,
//! `check_gap_a`) — the reference tie the successor arm re-wires
//! onto certificate-stratum reset rows.
//!
//! The test-side row emitter shares no code with the evaluator: it
//! writes `Op::Funa` rows directly from the synthetic declaration
//! indices (Qtsl boxes at dep 0, QtslCert for the grid complex / box
//! list / region atoms at dep 1).

mod common;

use common::{ev, ev_elems, qtslcert, qtslsys, QTSLCERT, QTSLSYS};
use geolog_envelope::body::Op;
use geolog_envelope::{ElemRef, Literal, Value};
use qtsl_geolog_provider::carillon::{
    check_dbar_closure, check_gap_a, ManifestData, ModeData, QBox as PureBox, TransitionData,
};
use qtsl_geolog_provider::qq::QQ;
use qtsl_geolog_provider::rowctx::CertRows;
use serde_json::Value as J;

const OWN: [u8; 32] = [0xCA; 32];

/// A rational as `(numerator, denominator)`.
type Q = (i64, u64);

fn lref(e: u32) -> Value {
    Value::Ref(ElemRef::Local(e))
}
fn qv(num: i64, den: u64) -> Value {
    Value::Lit(Literal::q(num, den).expect("canonical Q"))
}
fn shapev(xs: &[u64]) -> Value {
    Value::Lit(Literal::shape(xs))
}

/// The row emitter: independent of the evaluator's decode by
/// construction (raw `Op::Funa` writes against the two synthetic
/// indices).
struct Emit {
    ops: Vec<Op>,
    next: u32,
}

impl Emit {
    fn new() -> Emit {
        Emit {
            ops: Vec::new(),
            next: 0,
        }
    }

    fn xsys(name: &str) -> ElemRef {
        let c = qtslsys()
            .fun(name)
            .unwrap_or_else(|| panic!("qtslsys fun `{name}`"))
            .chid;
        assert_eq!(c.0, QTSLSYS);
        ElemRef::External {
            dep_index: 0,
            counter: c.1,
        }
    }

    fn xcert(name: &str) -> ElemRef {
        let c = qtslcert()
            .fun(name)
            .unwrap_or_else(|| panic!("qtslcert fun `{name}`"))
            .chid;
        assert_eq!(c.0, QTSLCERT);
        ElemRef::External {
            dep_index: 1,
            counter: c.1,
        }
    }

    fn alloc(&mut self) -> u32 {
        let e = self.next;
        self.next += 1;
        e
    }

    fn funa(&mut self, fun: ElemRef, args: Vec<Value>) -> u32 {
        let e = self.alloc();
        self.ops.push(Op::Funa {
            fun,
            args,
            value: lref(e),
        });
        e
    }

    /// A Qtsl Box element from `(lo, hi)` rational pairs.
    fn boxv(&mut self, ivs: &[(Q, Q)]) -> u32 {
        let mut tail = self.funa(Emit::xsys("boxNil"), vec![]);
        for &(lo, hi) in ivs.iter().rev() {
            // mkInterval fields bytewise: [hi, lo].
            let iv = self.funa(
                Emit::xsys("mkInterval"),
                vec![qv(hi.0, hi.1), qv(lo.0, lo.1)],
            );
            tail = self.funa(Emit::xsys("boxCons"), vec![lref(iv), lref(tail)]);
        }
        tail
    }

    fn int_box(&mut self, ivs: &[(i64, i64)]) -> u32 {
        let owned: Vec<((i64, u64), (i64, u64))> =
            ivs.iter().map(|&(l, h)| ((l, 1), (h, 1))).collect();
        self.boxv(&owned)
    }

    /// A QRatList element from rational cuts.
    fn ratlist(&mut self, cuts: &[(i64, u64)]) -> u32 {
        let mut tail = self.funa(Emit::xcert("qrlNil"), vec![]);
        for &(n, d) in cuts.iter().rev() {
            tail = self.funa(Emit::xcert("qrlCons"), vec![qv(n, d), lref(tail)]);
        }
        tail
    }

    /// A single-leaf, all-singleton, identity-chart grid complex over
    /// `dom` with the given per-axis INTERIOR cut lists (the v0
    /// profile's shape).
    fn gridcx(&mut self, dom: u32, interior: &[&[(i64, u64)]]) -> u32 {
        let mut gl = self.funa(Emit::xcert("qglNil"), vec![]);
        for cuts in interior.iter().rev() {
            let rl = self.ratlist(cuts);
            let gen = self.funa(Emit::xcert("qgenInterval"), vec![lref(rl)]);
            gl = self.funa(Emit::xcert("qglCons"), vec![lref(gen), lref(gl)]);
        }
        let chart = self.funa(Emit::xcert("qchIdentity"), vec![]);
        let part: Vec<u64> = (0..interior.len() as u64).collect();
        // qptLeaf fields bytewise: [chart, gens, part].
        let leaf = self.funa(
            Emit::xcert("qptLeaf"),
            vec![lref(chart), lref(gl), shapev(&part)],
        );
        // qgcMk fields bytewise: [dom, tree].
        self.funa(Emit::xcert("qgcMk"), vec![lref(dom), lref(leaf)])
    }

    /// A QBoxList element over Box elements.
    fn boxlist(&mut self, boxes: &[u32]) -> u32 {
        let mut tail = self.funa(Emit::xcert("qbxNil"), vec![]);
        for &b in boxes.iter().rev() {
            tail = self.funa(Emit::xcert("qbxCons"), vec![lref(b), lref(tail)]);
        }
        tail
    }

    fn qra_box(&mut self, b: u32) -> u32 {
        self.funa(Emit::xcert("qraBox"), vec![lref(b)])
    }

    fn rows(&self) -> CertRows {
        CertRows::from_ops(&self.ops, OWN, &[QTSLSYS, QTSLCERT])
    }
}

// ---------------------------------------------------------------------
// R3/R4: the event-3 loud-refusal fibers
// ---------------------------------------------------------------------
// The manifest jump/switch slice left the theory at the event-3
// closure; the row fibers refuse naming the stratum (never deciding),
// and the recompute semantics live in the pure core, replayed by the
// corpus below.

#[test]
fn dbar_row_fiber_refuses_named_stratum() {
    let mut e = Emit::new();
    let dbar = e.int_box(&[(1, 3)]);
    let m = e.alloc(); // a Manifest element (content irrelevant: the arm refuses first)
    let mode = e.alloc(); // a Mode element (the event-3 entity citation)
    let rows = e.rows();
    let err = ev(
        "qtsl_dbar_closure",
        &[&lref(dbar), &lref(m), &lref(mode)],
        &rows,
    )
    .unwrap_err();
    assert!(
        err.contains("not relationally exposed") && err.contains("refusing"),
        "the refusal names the retired stratum: {err}"
    );
}

#[test]
fn gap_a_row_fiber_refuses_named_stratum() {
    let mut e = Emit::new();
    let m = e.alloc();
    let rows = e.rows();
    let err = ev_elems("qtsl_gap_a", &[m], &rows).unwrap_err();
    assert!(
        err.contains("not relationally exposed") && err.contains("refusing"),
        "the refusal names the retired stratum: {err}"
    );
}

// ---------------------------------------------------------------------
// R2: qtsl_cell_cover
// ---------------------------------------------------------------------

/// The 2-D fixture grid over [0,4]²: axis 0 cut at {1,2,3}, axis 1 at
/// {2} — 4 × 2 cells, idx = c0 + 4·c1 (axis 0 fastest).
fn grid_4x2(e: &mut Emit) -> u32 {
    let dom = e.int_box(&[(0, 4), (0, 4)]);
    e.gridcx(dom, &[&[(1, 1), (2, 1), (3, 1)], &[(2, 1)]])
}

#[test]
fn cell_cover_golden_exact_span_holds() {
    let mut e = Emit::new();
    let cx = grid_4x2(&mut e);
    let region = e.int_box(&[(1, 3), (0, 2)]);
    let rows = e.rows();
    assert_eq!(
        ev(
            "qtsl_cell_cover",
            &[&shapev(&[1, 2]), &lref(cx), &lref(region)],
            &rows
        ),
        Ok(true)
    );
}

#[test]
fn cell_cover_golden_unaligned_region() {
    // [1/2, 3/2] × [1, 3] meets axis-0 cells {0,1}, axis-1 cells
    // {0,1}: needs {0, 1, 4, 5}.
    let mut e = Emit::new();
    let cx = grid_4x2(&mut e);
    let region = e.boxv(&[((1, 2), (3, 2)), ((1, 1), (3, 1))]);
    let rows = e.rows();
    assert_eq!(
        ev(
            "qtsl_cell_cover",
            &[&shapev(&[0, 1, 4, 5]), &lref(cx), &lref(region)],
            &rows
        ),
        Ok(true)
    );
    assert_eq!(
        ev(
            "qtsl_cell_cover",
            &[&shapev(&[0, 1, 4]), &lref(cx), &lref(region)],
            &rows
        ),
        Ok(false)
    );
}

