#[test]
fn floor_golden_exact_single_box() {
    // T = [0,2]∩[1,3] = [1,2]; cover = [T].
    let mut e = Emit::new();
    let c0 = e.int_box(&[(1, 2)]);
    let cover = e.boxlist(&[c0]);
    let dbar = e.int_box(&[(1, 3)]);
    let bx = e.int_box(&[(0, 2)]);
    let region = e.qra_box(bx);
    let rows = e.rows();
    assert_eq!(
        ev(
            "qtsl_lowbound_boxes",
            &[&lref(cover), &lref(dbar), &lref(region)],
            &rows
        ),
        Ok(true)
    );
}

#[test]
fn floor_golden_2d_tiling() {
    // T = [0,2]²; four unit tiles cover it; dropping one leaves a
    // hole.
    let mut e = Emit::new();
    let t00 = e.int_box(&[(0, 1), (0, 1)]);
    let t10 = e.int_box(&[(1, 2), (0, 1)]);
    let t01 = e.int_box(&[(0, 1), (1, 2)]);
    let t11 = e.int_box(&[(1, 2), (1, 2)]);
    let full = e.boxlist(&[t00, t10, t01, t11]);
    let dbar = e.int_box(&[(0, 2), (0, 2)]);
    let bx = e.int_box(&[(0, 2), (0, 2)]);
    let region = e.qra_box(bx);
    let rows = e.rows();
    assert_eq!(
        ev(
            "qtsl_lowbound_boxes",
            &[&lref(full), &lref(dbar), &lref(region)],
            &rows
        ),
        Ok(true)
    );

    let mut e2 = Emit::new();
    let t00 = e2.int_box(&[(0, 1), (0, 1)]);
    let t10 = e2.int_box(&[(1, 2), (0, 1)]);
    let t01 = e2.int_box(&[(0, 1), (1, 2)]);
    let l3 = e2.boxlist(&[t00, t10, t01]);
    let dbar = e2.int_box(&[(0, 2), (0, 2)]);
    let bx = e2.int_box(&[(0, 2), (0, 2)]);
    let region = e2.qra_box(bx);
    let rows2 = e2.rows();
    assert_eq!(
        ev(
            "qtsl_lowbound_boxes",
            &[&lref(l3), &lref(dbar), &lref(region)],
            &rows2
        ),
        Ok(false)
    );
}

