#[test]
fn floor_refusal_non_box_atom() {
    // A sublevel atom is the RCert seam: refusal by name.
    let mut e = Emit::new();
    let c0 = e.int_box(&[(1, 2)]);
    let cover = e.boxlist(&[c0]);
    let dbar = e.int_box(&[(1, 3)]);
    let fam = e.alloc(); // an unconstructed QCertFam element
    let atom = e.funa(Emit::xcert("qraSublevel"), vec![lref(fam), qv(1, 1)]);
    let rows = e.rows();
    let err = ev(
        "qtsl_lowbound_boxes",
        &[&lref(cover), &lref(dbar), &lref(atom)],
        &rows,
    )
    .unwrap_err();
    assert!(err.contains("not a qraBox"), "got: {err}");
}

#[test]
fn floor_refusal_arity_mismatch() {
    let mut e = Emit::new();
    let c0 = e.int_box(&[(1, 2)]);
    let cover = e.boxlist(&[c0]);
    let dbar = e.int_box(&[(1, 3), (0, 1)]);
    let bx = e.int_box(&[(0, 2)]);
    let region = e.qra_box(bx);
    let rows = e.rows();
    let err = ev(
        "qtsl_lowbound_boxes",
        &[&lref(cover), &lref(dbar), &lref(region)],
        &rows,
    )
    .unwrap_err();
    assert!(err.contains("arity"), "got: {err}");
}

#[test]
fn floor_refusal_cyclic_cover_list() {
    // A box list whose tail recurs: P-ACYCLIC territory, refused.
    let mut e = Emit::new();
    let dbar = e.int_box(&[(1, 3)]);
    let bx = e.int_box(&[(0, 2)]);
    let region = e.qra_box(bx);
    let b0 = e.int_box(&[(1, 2)]);
    let cyc = e.alloc();
    e.ops.push(Op::Funa {
        fun: Emit::xcert("qbxCons"),
        args: vec![lref(b0), lref(cyc)],
        value: lref(cyc),
    });
    let rows = e.rows();
    let err = ev(
        "qtsl_lowbound_boxes",
        &[&lref(cyc), &lref(dbar), &lref(region)],
        &rows,
    )
    .unwrap_err();
    assert!(err.contains("recurs"), "got: {err}");
}

// ---------------------------------------------------------------------
// The frozen cross-implementation corpus
// ---------------------------------------------------------------------

fn jq(v: &J) -> (i64, u64) {
    let a = v.as_array().expect("rational pair");
    (a[0].as_i64().expect("num"), a[1].as_u64().expect("den"))
}

fn jbox(v: &J) -> Vec<((i64, u64), (i64, u64))> {
    v.as_array()
        .expect("box")
        .iter()
        .map(|iv| {
            let iv = iv.as_array().expect("interval");
            (jq(&iv[0]), jq(&iv[1]))
        })
        .collect()
}

fn pure_qq(pair: (i64, u64)) -> QQ {
    let l = geolog_envelope::Literal::q(pair.0, pair.1).expect("canonical Q");
    QQ::from_q_literal(&l).expect("Q literal decodes")
}

fn pure_box(v: &J) -> PureBox {
    jbox(v)
        .into_iter()
        .map(|(lo, hi)| (pure_qq(lo), pure_qq(hi)))
        .collect()
}

/// Build the pure-core manifest from a corpus case (the row fiber
/// refuses at event-3; the reference tie replays on the pure checks).
fn pure_manifest(case: &J) -> ManifestData {
    let modes = case["modes"]
        .as_array()
        .expect("modes")
        .iter()
        .map(|md| ModeData {
            name: md["name"].as_str().expect("name").to_string(),
            domain: pure_box(&md["domain"]),
            jump_images: md["jump_images"]
                .as_array()
                .expect("jump_images")
                .iter()
                .map(pure_box)
                .collect(),
        })
        .collect();
    let transitions = case["transitions"]
        .as_array()
        .expect("transitions")
        .iter()
        .map(|td| TransitionData {
            src: td["src"].as_str().expect("src").to_string(),
            dst: td["dst"].as_str().expect("dst").to_string(),
            reset_image: pure_box(&td["reset_image"]),
        })
        .collect();
    ManifestData { modes, transitions }
}

#[test]
fn corpus_replay() {
    let raw = include_str!("fixtures/carillon_pyref_corpus.json");
    let c: J = serde_json::from_str(raw).expect("corpus parses");
    let cases = c["cases"].as_array().expect("cases");
    let counts = &c["counts"];
    assert_eq!(
        counts["total"].as_u64().expect("total") as usize,
        cases.len()
    );

    let mut holds = 0u64;
    for (ci, case) in cases.iter().enumerate() {
        let kind = case["kind"].as_str().expect("kind");
        let expected = case["verdict"].as_bool().expect("verdict");
        holds += expected as u64;
        let got = match kind {
            "dbar" => {
                // Pure-core replay: the corpus verdicts are decided
                // content, and a pure-check refusal on an in-domain
                // case would be a corpus divergence (mapped to Err).
                let m = pure_manifest(case);
                let dbar = pure_box(&case["dbar"]);
                let mode = case["mode"].as_str().expect("mode");
                check_dbar_closure(&dbar, &m, mode).map(|v| v.is_ok())
            }
            "gap_a" => {
                let m = pure_manifest(case);
                check_gap_a(&m).map(|v| v.is_ok())
            }
            "cell_cover" => {
                let mut e = Emit::new();
                let dom = jbox(&case["dom"]);
                let dom = e.boxv(&dom);
                let interior: Vec<Vec<(i64, u64)>> = case["cuts"]
                    .as_array()
                    .expect("cuts")
                    .iter()
                    .map(|axis| axis.as_array().expect("axis").iter().map(jq).collect())
                    .collect();
                let refs: Vec<&[(i64, u64)]> = interior.iter().map(|a| a.as_slice()).collect();
                let cx = e.gridcx(dom, &refs);
                let region = jbox(&case["region"]);
                let region = e.boxv(&region);
                let cells: Vec<u64> = case["cells"]
                    .as_array()
                    .expect("cells")
                    .iter()
                    .map(|v| v.as_u64().expect("cell"))
                    .collect();
                let rows = e.rows();
                ev(
                    "qtsl_cell_cover",
                    &[&shapev(&cells), &lref(cx), &lref(region)],
                    &rows,
                )
            }
            "floor_boxes" => {
                let mut e = Emit::new();
                let mut parts = Vec::new();
                for b in case["cover"].as_array().expect("cover") {
                    let b = jbox(b);
                    parts.push(e.boxv(&b));
                }
                let cover = e.boxlist(&parts);
                let dbar = jbox(&case["dbar"]);
                let dbar = e.boxv(&dbar);
                let bx = jbox(&case["bx"]);
                let bx = e.boxv(&bx);
                let region = e.qra_box(bx);
                let rows = e.rows();
                ev(
                    "qtsl_lowbound_boxes",
                    &[&lref(cover), &lref(dbar), &lref(region)],
                    &rows,
                )
            }
            other => panic!("unknown corpus kind `{other}`"),
        };
        assert_eq!(
            got,
            Ok(expected),
            "corpus divergence at case {ci} (kind {kind}): {case}"
        );
    }
    assert_eq!(holds, counts["holds"].as_u64().expect("holds"));
}
